package com.metaplatform.agent.runs;
import jakarta.persistence.*; import lombok.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.annotations.SQLRestriction; import org.hibernate.type.SqlTypes; import java.time.Instant;
@Entity @Table(name="agent_runs") @SQLRestriction("revoked_at IS NULL") @Data @Builder @NoArgsConstructor @AllArgsConstructor
public class AgentRunEntity { @Id @Column(name="run_id",length=64) private String runId; @Column(name="tenant_id",nullable=false,length=64) private String tenantId; @Column(name="user_id",nullable=false,length=64) private String userId; @Column(name="agent_id",nullable=false,length=128) private String agentId; @Column(name="runtime_type",nullable=false,length=32) private String runtimeType; @Column(name="context_envelope_id",length=64) private String contextEnvelopeId; @Column(nullable=false,length=32) private String status; @Column(nullable=false,columnDefinition="TEXT") private String goal; @Column(name="parent_run_id",length=64) private String parentRunId; @Lob @JdbcTypeCode(SqlTypes.JSON) @Column(nullable=false,columnDefinition="jsonb") private String budget; @Column(name="trace_id",nullable=false,length=64) private String traceId; @Column(name="deerflow_thread_id",length=64) private String deerflowThreadId; @Column(name="deerflow_run_id",length=64) private String deerflowRunId; @Column(name="started_at") private Instant startedAt; @Column(name="finished_at") private Instant finishedAt; @Column(name="error_code",length=64) private String errorCode; @Column(name="error_message",columnDefinition="TEXT") private String errorMessage; @Column(name="revoked_at") private Instant revokedAt; @Column(name="revoked_by",length=64) private String revokedBy; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt; }
